import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

function Appointments() {
  const [appointments, setAppointments] = useState([]);
  const [doctors, setDoctors] = useState([]);
  const [newAppointment, setNewAppointment] = useState({
    doctorId: '',
    department: '',
    date: '',
    time: '',
    reason: ''
  });
  const [loading, setLoading] = useState(true);

  const navigate = useNavigate();
  const userEmail = localStorage.getItem('userEmail');
  const userRole = localStorage.getItem('userRole');

  // 添加返回首页功能
  const handleGoBack = () => {
    navigate('/home');
  };

  useEffect(() => {
    // 检查用户权限
    if (!userEmail || userRole !== 'client') {
      navigate('/login');
      return;
    }

    // 加载预约数据和医生列表
    fetchAppointments();
    fetchDoctors();
  }, [userEmail, userRole, navigate]);

  const fetchAppointments = async () => {
    try {
      setLoading(true);
      const response = await fetch(`http://localhost:5001/api/appointments/patient?email=${userEmail}`);
      if (response.ok) {
        const data = await response.json();
        setAppointments(data);
      } else {
        console.error('Failed to fetch appointments');
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const fetchDoctors = async () => {
    try {
      const response = await fetch('http://localhost:5001/api/appointments/doctors');
      if (response.ok) {
        const data = await response.json();
        setDoctors(data.length > 0 ? data : [
          { _id: '1', fullName: 'Dr. Lee - Cardiology' },
          { _id: '2', fullName: 'Dr. Wang - Neurology' },
          { _id: '3', fullName: 'Dr. Johnson - Orthopedics' }
        ]);
      } else {
        console.error('Failed to fetch doctors');
      }
    } catch (err) {
      console.error(err);
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setNewAppointment({
      ...newAppointment,
      [name]: value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const response = await fetch('http://localhost:5001/api/appointments', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          email: userEmail,
          ...newAppointment
        }),
      });

      if (response.ok) {
        alert('Appointment booked successfully!');
        setNewAppointment({
          doctorId: '',
          department: '',
          date: '',
          time: '',
          reason: ''
        });
        fetchAppointments(); // 刷新预约列表
      } else {
        const errorData = await response.json();
        alert(`Failed to book appointment: ${errorData.message || 'Unknown error'}`);
      }
    } catch (err) {
      console.error(err);
      alert('An error occurred. Please try again.');
    }
  };

  const handleCancel = async (id) => {
    if (!window.confirm('Are you sure you want to cancel this appointment?')) {
      return;
    }

    try {
      const response = await fetch(`http://localhost:5001/api/appointments/cancel/${id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ email: userEmail }),
      });

      if (response.ok) {
        alert('Appointment cancelled successfully!');
        fetchAppointments(); // 刷新预约列表
      } else {
        alert('Failed to cancel appointment.');
      }
    } catch (err) {
      console.error(err);
      alert('An error occurred. Please try again.');
    }
  };

  const getStatusBadge = (status) => {
    switch (status) {
      case 'pending':
        return <span className="badge bg-warning">Pending</span>;
      case 'confirmed':
        return <span className="badge bg-success">Confirmed</span>;
      case 'cancelled':
        return <span className="badge bg-danger">Cancelled</span>;
      case 'completed':
        return <span className="badge bg-info">Completed</span>;
      default:
        return <span className="badge bg-secondary">Unknown</span>;
    }
  };

  if (loading) {
    return <div className="text-center mt-5">Loading...</div>;
  }

  return (
    <>
      <div className="login-background"></div>
      <div className="container mt-5">
        {/* 添加返回按钮 */}
        <div className="d-flex justify-content-between align-items-center mb-3">
          <h2 className="text-white">Appointment Management</h2>
          <button className="btn btn-outline-light" onClick={handleGoBack}>
            Back to Home
          </button>
        </div>

        {/* Book New Appointment */}
        <div className="card mb-4">
          <div className="card-header bg-primary text-white">
            <h4>Schedule New Appointment</h4>
          </div>
          <div className="card-body">
            <form onSubmit={handleSubmit}>
              <div className="row">
                <div className="col-md-6 mb-3">
                  <label className="form-label">Select Doctor</label>
                  <select
                    className="form-select"
                    name="doctorId"
                    value={newAppointment.doctorId}
                    onChange={handleInputChange}
                    required
                  >
                    <option value="">-- Select Doctor --</option>
                    {doctors.map(doctor => (
                      <option key={doctor._id} value={doctor._id}>
                        {doctor.fullName}
                      </option>
                    ))}
                  </select>
                </div>
                <div className="col-md-6 mb-3">
                  <label className="form-label">Department</label>
                  <select
                    className="form-select"
                    name="department"
                    value={newAppointment.department}
                    onChange={handleInputChange}
                    required
                  >
                    <option value="">-- Select Department --</option>
                    <option value="Cardiology">Cardiology</option>
                    <option value="Neurology">Neurology</option>
                    <option value="Pediatrics">Pediatrics</option>
                    <option value="Orthopedics">Orthopedics</option>
                    <option value="Dermatology">Dermatology</option>
                    <option value="Ophthalmology">Ophthalmology</option>
                    <option value="General Medicine">General Medicine</option>
                  </select>
                </div>
              </div>

              <div className="row">
                <div className="col-md-6 mb-3">
                  <label className="form-label">Date</label>
                  <input
                    type="date"
                    className="form-control"
                    name="date"
                    value={newAppointment.date}
                    onChange={handleInputChange}
                    required
                  />
                </div>
                <div className="col-md-6 mb-3">
                  <label className="form-label">Time</label>
                  <input
                    type="time"
                    className="form-control"
                    name="time"
                    value={newAppointment.time}
                    onChange={handleInputChange}
                    required
                  />
                </div>
              </div>

              <div className="mb-3">
                <label className="form-label">Reason for Visit</label>
                <textarea
                  className="form-control"
                  name="reason"
                  rows="3"
                  value={newAppointment.reason}
                  onChange={handleInputChange}
                  required
                ></textarea>
              </div>

              <button type="submit" className="btn btn-primary">Book Appointment</button>
            </form>
          </div>
        </div>

        {/* My Appointments */}
        <div className="card">
          <div className="card-header bg-primary text-white">
            <h4>My Appointments</h4>
          </div>
          <div className="card-body">
            {appointments.length > 0 ? (
              <div className="table-responsive">
                <table className="table table-striped">
                  <thead>
                    <tr>
                      <th>Doctor</th>
                      <th>Department</th>
                      <th>Date</th>
                      <th>Time</th>
                      <th>Status</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {appointments.map(appointment => (
                      <tr key={appointment._id}>
                        <td>{appointment.doctorId.fullName}</td>
                        <td>{appointment.department}</td>
                        <td>{new Date(appointment.date).toLocaleDateString()}</td>
                        <td>{appointment.time}</td>
                        <td>{getStatusBadge(appointment.status)}</td>
                        <td>
                          {appointment.status === 'pending' && (
                            <button
                              className="btn btn-sm btn-danger"
                              onClick={() => handleCancel(appointment._id)}
                            >
                              Cancel
                            </button>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            ) : (
              <p className="text-center">No appointment records. Book your first appointment now!</p>
            )}
          </div>
        </div>
      </div>
    </>
  );
}

export default Appointments;
